begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
select ok(not has_function_privilege('anon','public.edit_collection_copies(uuid,uuid,jsonb,jsonb)','execute'),'anonymous edits denied');
insert into auth.users(id,email) values('15000000-0000-0000-0000-000000000001','copy-editor@shogun.test'),('15000000-0000-0000-0000-000000000002','copy-viewer@shogun.test');
set local role authenticated;
select set_config('request.jwt.claim.sub','15000000-0000-0000-0000-000000000001',true);
select public.create_collection_library('25000000-0000-0000-0000-000000000001','Edit copies');
select public.add_manual_movie('45000000-0000-0000-0000-000000000001','25000000-0000-0000-0000-000000000001','{"title":"Keep metadata","genres":[]}','["DVD","DVD"]');
select set_config('test.movie',(select id::text from public.movies where title='Keep metadata'),true);
select set_config('test.expected',(select jsonb_agg(jsonb_build_object('id',id,'format',format) order by id)::text from public.owned_copies where library_id='25000000-0000-0000-0000-000000000001'),true);
select public.save_movie_diary(current_setting('test.movie')::uuid,true,4::smallint);
select lives_ok($$select public.edit_collection_copies('25000000-0000-0000-0000-000000000001',current_setting('test.movie')::uuid,current_setting('test.expected')::jsonb,'["Blu-ray","Blu-ray","DVD"]')$$,'formats and quantities edited');
select lives_ok($$select public.edit_collection_copies('25000000-0000-0000-0000-000000000001',current_setting('test.movie')::uuid,current_setting('test.expected')::jsonb,'["Blu-ray","Blu-ray","DVD"]')$$,'lost-response retry does not duplicate');
select is((select count(*) from public.owned_copies where library_id='25000000-0000-0000-0000-000000000001'),3::bigint,'exact desired quantity');
select is((select title from public.movies where id=current_setting('test.movie')::uuid),'Keep metadata','metadata unchanged');
select is((select rating from public.personal_movie_state where movie_id=current_setting('test.movie')::uuid),4::smallint,'diary unchanged');
select throws_ok($$select public.edit_collection_copies('25000000-0000-0000-0000-000000000001',current_setting('test.movie')::uuid,current_setting('test.expected')::jsonb,'["VHS"]')$$,'PT409',null,'stale draft cannot overwrite changes');
select set_config('request.jwt.claim.sub','15000000-0000-0000-0000-000000000002',true);
select throws_ok($$select public.edit_collection_copies('25000000-0000-0000-0000-000000000001',current_setting('test.movie')::uuid,'[]','[]')$$,'42501',null,'outsider denied');
reset role;
insert into public.library_memberships values('25000000-0000-0000-0000-000000000001','15000000-0000-0000-0000-000000000002','editor');
set local role authenticated;
select set_config('test.expected',(select jsonb_agg(jsonb_build_object('id',id,'format',format) order by id)::text from public.owned_copies where library_id='25000000-0000-0000-0000-000000000001'),true);
select lives_ok($$select public.edit_collection_copies('25000000-0000-0000-0000-000000000001',current_setting('test.movie')::uuid,current_setting('test.expected')::jsonb,'["VHS"]')$$,'editor can edit shared manual movie');
select set_config('test.expected',(select jsonb_agg(jsonb_build_object('id',id,'format',format) order by id)::text from public.owned_copies where library_id='25000000-0000-0000-0000-000000000001'),true);
select lives_ok($$select public.edit_collection_copies('25000000-0000-0000-0000-000000000001',current_setting('test.movie')::uuid,current_setting('test.expected')::jsonb,'[]')$$,'zero removes library copies');
select lives_ok($$select public.edit_collection_copies('25000000-0000-0000-0000-000000000001',current_setting('test.movie')::uuid,current_setting('test.expected')::jsonb,'[]')$$,'zero removal retry safe');
select throws_ok($$select public.edit_collection_copies('25000000-0000-0000-0000-000000000001',current_setting('test.movie')::uuid,'[]','["DVD"]')$$,'PT409',null,'cannot attach an inaccessible manual movie');
select * from finish();
rollback;
